// Діагностика завантаження веб-клієнта: консоль, мережа, кадри, очікування полів до 60 с.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors: true, viewport: {width:1280, height:800}, locale: 'uk-UA' });
  const page = await ctx.newPage();
  const errs = [];
  page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE: ' + m.text().slice(0,120)); });
  page.on('pageerror', e => errs.push('PAGEERR: ' + String(e).slice(0,120)));
  page.on('requestfailed', r => errs.push('REQFAIL: ' + r.url().slice(-80) + ' ' + (r.failure()||{}).errorText));
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil: 'load', timeout: 60000 });
  let found = null;
  for (let i = 0; i < 12; i++) {
    await page.waitForTimeout(5000);
    const n = await page.$$eval('input', ns => ns.filter(x => x.offsetWidth||x.offsetHeight).length).catch(()=>0);
    const txt = await page.evaluate(() => document.body.innerText.trim().length).catch(()=>0);
    console.log('крок %d: видимих input=%d, тексту=%d символів', i+1, n, txt);
    if (n > 0) { found = n; break; }
  }
  await page.screenshot({ path: '/root/webbot/shots/10-diag.png' });
  console.log('FRAMES:', page.frames().map(f => f.url().slice(-50)).join(' | '));
  const html = await page.content();
  console.log('HTML довжина:', html.length);
  console.log('HTML шматок:', html.replace(/\s+/g,' ').slice(0, 500));
  console.log('ПОМИЛКИ (%d):', errs.length);
  for (const e of errs.slice(0, 10)) console.log('  ', e);
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0, 300)); process.exit(1); });
JSEOF
cd /root/webbot && timeout 115 node login_test2.js 2>&1 | tail -25
